from rdkit import Chem

# Input SMILES
smiles = "Cc1nc2ccc(-c3ccc([C@H](C)N4CC[C@](CC(C)(C)O)(c5ccccc5)OC4=O)cc3)cc2[nH]1"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Molecule is valid")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find the morpholinone ring
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AMIDE or bond.GetBondType() == Chem.BondType.TRIPLE:
            continue
        if bond.GetBeginAtom().GetSymbol() == 'O' and bond.GetEndAtom().GetSymbol() == 'C':
            if bond.GetBeginAtom().IsInRing() and bond.GetEndAtom().IsInRing():
                begin_ring = bond.GetBeginAtom().GetIdx()
                end_ring = bond.GetEndAtom().GetIdx()
                # Check if this could be a lactam/lactone carbonyl
                if bond.GetBondType() == Chem.BondType.DOUBLE:
                    print(f"Possible carbonyl at O{begin_ring}=C{end_ring}")

    # Look for N-C(=O) bonds (amide/lactam)
    for atom in mol.GetAtoms():
        if atom.GetSymbol() == 'N' and atom.IsInRing():
            for neighbor in atom.GetNeighbors():
                if neighbor.GetSymbol() == 'C':
                    for nbor in neighbor.GetNeighbors():
                        if nbor.GetSymbol() == 'O' and neighbor.GetBondWithNeighbor(nbor).GetBondType() == Chem.BondType.DOUBLE:
                            print(f"Lactam: N{atom.GetIdx()} connected to C{neighbor.GetIdx}(=O)")

    # Print all ring systems
    ssrs = Chem.GetSymmSSSR(mol)
    print(f"\nRing systems ({len(ssrs)}):")
    for i, ring in enumerate(ssrs):
        ring_atoms = [mol.GetAtomWithIdx(idx).GetSymbol() for idx in ring]
        print(f"  Ring {i+1}: {'-'.join(ring_atoms)}")

    # Check stereochemistry
    chiral_centers = []
    for atom in mol.GetAtoms():
        if atom.HasProp('_ChiralityPossible'):
            chiral_centers.append((atom.GetIdx(), atom.GetChiralTag()))
    print(f"\nChiral centers: {chiral_centers}")
else:
    print("Invalid SMILES")
